/*
 * PowerData: CAN ID 0x500 (standard), 8 bytes, sender ECM
 *
 * C struct generated by CanViewer from demo.dbc.
 * Each member holds the raw value of a signal; physical value = raw * factor + offset.
 */
#include <stdint.h>

#define POWERDATA_ID 0x500u
#define POWERDATA_IS_EXTENDED 0
#define POWERDATA_LENGTH 8u

typedef struct {
    /* start bit 0, 32 bits, Intel, float32 (IEEE 754), factor 1, offset 0, range 0 .. 100 V */
    float BatteryVoltage;
    /* start bit 32, 16 bits, Intel, unsigned, factor 0.1, offset 0, range 0 .. 6553.5 l/h */
    uint16_t Consumption;
} PowerData_t;
